#!/usr/bin/env node
// Foundry addition (not upstream bento).
//
// Regenerates slides/src/foundry/fontdata.ts — the base64 woff2 for the brand
// faces embedded in the shell. Upstream embeds its starter-deck faces the same
// way (slides/src/fontdata.ts): a Bento file must make ZERO external requests,
// so a font either travels inside the file or isn't used.
//
//   npm run fonts:refresh    (from vendor/bento/slides)
//
// Only re-run this if a face needs updating — the generated file is committed
// and the build does not depend on network access.
//
// All three faces are SIL Open Font License 1.1 (see THIRD_PARTY_NOTICES.md).

import { writeFileSync } from 'node:fs'

const UA =
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'

// Google serves one @font-face per subset; the latin block is the one carrying
// U+0131 (dotless i) alongside U+0000-00FF.
const LATIN_MARKERS = ['U+0000-00FF', 'U+0131']

async function grab(query) {
  const cssRes = await fetch(`https://fonts.googleapis.com/css2?${query}`, {
    headers: { 'User-Agent': UA },
  })
  if (!cssRes.ok) throw new Error(`google fonts css ${cssRes.status} for ${query}`)
  const blocks = (await cssRes.text()).split('@font-face').slice(1)
  const latin = blocks.find((b) => LATIN_MARKERS.every((m) => b.includes(m))) ?? blocks.at(-1)
  const url = /url\((https:[^)]+)\)/.exec(latin)?.[1]
  if (!url) throw new Error(`no woff2 url in the latin block for ${query}`)
  const buf = Buffer.from(await (await fetch(url)).arrayBuffer())
  return { url, b64: buf.toString('base64'), kb: (buf.length / 1024).toFixed(1) }
}

const faces = {
  INTER_VAR: {
    query: 'family=Inter:wght@400..600&display=swap',
    note: 'UI sans, DESIGN.md {typography.body-*}',
  },
  JETBRAINS_MONO_VAR: {
    query: 'family=JetBrains+Mono:wght@400..600&display=swap',
    note: 'widget headers + data labels',
  },
  DM_SERIF_DISPLAY_400: {
    query: 'family=DM+Serif+Display&display=swap',
    note: 'editorial/stat display',
  },
}

for (const [name, face] of Object.entries(faces)) {
  Object.assign(face, await grab(face.query))
  console.log(`${name} — ${face.kb}KB`)
}

const list = Object.entries(faces)
const header =
  `// Foundry addition (not upstream bento) — SPDX-License-Identifier: OFL-1.1\n` +
  `// GENERATED by scripts/refresh-brand-fonts.mjs — do not hand-edit.\n` +
  `//\n` +
  `// Brand faces for the Foundry/Gitwork chrome, embedded the same way upstream\n` +
  `// embeds its starter-deck faces in fontdata.ts: base64 woff2 in the bundle, so a\n` +
  `// saved deck stays a single file with ZERO external requests (the bento contract).\n` +
  `// Latin subsets only. All SIL Open Font License 1.1 — see THIRD_PARTY_NOTICES.md.\n` +
  `//\n` +
  list.map(([n, f]) => `//   ${n} (${f.kb}KB) — ${f.note}\n//     ${f.url}`).join('\n') +
  `\n\n`

writeFileSync(
  new URL('../slides/src/foundry/fontdata.ts', import.meta.url),
  header + list.map(([n, f]) => `export const ${n} = 'data:font/woff2;base64,${f.b64}'\n`).join('\n'),
)
console.log('wrote slides/src/foundry/fontdata.ts')
